// Derived distinct grouped projects
export const PROJECT_GROUPS: ProjectGroup[] = (() => {
  const map = new Map<string, ProjectGroup>();
  for (const img of ALL_PROJECT_IMAGES) {
    if (!map.has(img.projectId)) {
      map.set(img.projectId, {
        projectId: img.projectId,
        title: img.title,
        client: img.client,
        category: img.category,
        categoryLabel: img.categoryLabel,
        event: img.event,
        location: img.location,
        year: img.year,
        boothNumber: img.boothNumber,
        specs: img.specs,
        description: img.description,
        leadImage: img,
        images: [],
        size: img.size,
        designType: img.designType,
        inclusions: img.inclusions,
        materials: img.materials,
        addons: img.addons,
        buildTime: img.buildTime,
      });
    }
    const group = map.get(img.projectId)!;
    group.images.push(img);
    if (img.isLead) {
      group.leadImage = img;
    }
  }
  return Array.from(map.values());
})();

